{
  "message": "Calculator updated with Clear button and keyboard input.",
   "artifact": {
      "title": "Simple Calculator",
      "language": "html",
      "content": "<html><head><title>Simple Calculator</title><style>body { font-family: monospace; }</style></head><body><h1>Simple Calculator</h1><input id=\"num1\" type=\"number\" placeholder=\"Number 1\"><br><input id=\"operator\" type=\"text\" placeholder=\"+,-,*,/\"><br><input id=\"num2\" type=\"number\" placeholder=\"Number 2\"><br><button id=\"calculate\">Calculate</button><button id=\"clear\">Clear</button><br><div id=\"result\"></div><script>document.addEventListener('keydown', function(event) { if (event.key === 'Enter') { document.getElementById('calculate').click(); } });document.getElementById('calculate').addEventListener('click', function() { let num1 = parseFloat(document.getElementById('num1').value); let operator = document.getElementById('operator').value; let num2 = parseFloat(document.getElementById('num2').value); let result; switch (operator) { case '+': result = num1 + num2; break; case '-': result = num1 - num2; break; case '*': result = num1 * num2; break; case '/': if (num2 != 0) result = num1 / num2; else result = 'Error: Division by zero'; break; default: result = 'Error: Invalid operator'; } document.getElementById('result').innerText = result; });document.getElementById('clear').addEventListener('click', function() { document.getElementById('num1').value = ''; document.getElementById('operator').value = ''; document.getElementById('num2').value = ''; document.getElementById('result').innerText = ''; });</script></body></html>"
   }
}
